import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

export interface ReportDatePickerProps {
  value?: Date | null;
  onChange?: (value: Date | null) => void;
}

const startOfDay = (date: Date): Date =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number): Date => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() - days);
  return base;
};

const isSameDay = (a: Date | null | undefined, b: Date): boolean =>
  !!a && startOfDay(a).getTime() === b.getTime();

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(value ?? null);
  const selected = value !== undefined ? value : internalDate;

  const presets = [
    { key: 'today', label: 'Сегодня', date: shiftDays(0) },
    { key: 'yesterday', label: 'Вчера', date: shiftDays(1) },
    { key: 'week', label: 'Неделя назад', date: shiftDays(7) },
  ];

  const select = (next: Date | null) => {
    if (value === undefined) {
      setInternalDate(next);
    }
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.key}
            active={isSameDay(selected, preset.date)}
            onClick={() => select(preset.date)}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar
        locale="ru-RU"
        value={selected}
        onValueChange={select}
        aria-label="Дата отчёта"
      />
    </div>
  );
}

